ListNode* removeNthFromEnd(ListNode* head, int n) {
    ListNode dummy(0);
    dummy.next = head;
    ListNode *fast = &dummy, *slow = &dummy;
    for (int i = 0; i <= n; i++) fast = fast->next; // 快指针先走N+1步
    while (fast) {
        fast = fast->next;
        slow = slow->next;
    }
    ListNode* del = slow->next;
    slow->next = slow->next->next;
    delete del;  // C++手动释放
    return dummy.next;
}
// 快指针先走N+1步(因为要定位到待删节点的前驱) | dummy不可或缺
